from collections import deque
def f(g):
    h,w=len(g),len(g[0])
    from collections import Counter
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    seen=[[False]*w for _ in range(h)]
    comps=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]==bg and not seen[i][j]:
                q=deque([(i,j)]); seen[i][j]=True; cells=[]
                touch=False
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    if a in (0,h-1) or b in (0,w-1): touch=True
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<h and 0<=y<w and g[x][y]==bg and not seen[x][y]:
                            seen[x][y]=True; q.append((x,y))
                if not touch:
                    rs=[c[0] for c in cells]; cs=[c[1] for c in cells]
                    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                    rect = len(cells)==(r1-r0+1)*(c1-c0+1)
                    comps.append((rect,cells))
    out=[row[:] for row in g]
    for rect,cells in comps:
        if rect:
            for a,b in cells: out[a][b]=4
    return out
